#!/usr/bin/env python3
"""Rafiq solution note — 2-page A4 PDF (ReportLab, report brief).
Palette: pdf.py palette.cascade --harmony monochrome --seed 7 (copied verbatim below).
"""
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import (BaseDocTemplate, Frame, PageTemplate, Paragraph,
                                Spacer, Table, TableStyle, KeepTogether)

# ━━ Color Palette (auto-generated by pdf.py palette.cascade, monochrome seed 7) ━━
PAGE_BG    = colors.HexColor("#f5f6f6")
CARD_BG    = colors.HexColor("#e4e8ea")
STRIPE     = colors.HexColor("#edefef")
HEADER     = colors.HexColor("#455964")
BORDER     = colors.HexColor("#b7cad3")
ICON       = colors.HexColor("#3a667d")
ACCENT     = colors.HexColor("#277da8")
TEXT       = colors.HexColor("#232527")
MUTED      = colors.HexColor("#777e81")

W, H = A4
M = 15 * mm
AVAIL = W - 2 * M

S = {
    "title":  ParagraphStyle("title", fontName="Helvetica-Bold", fontSize=19, leading=22,
                             textColor=TEXT),
    "meta":   ParagraphStyle("meta", fontName="Helvetica", fontSize=9.5, leading=13,
                             textColor=MUTED),
    "h2":     ParagraphStyle("h2", fontName="Helvetica-Bold", fontSize=11.5, leading=14,
                             textColor=ICON, spaceBefore=9, spaceAfter=3),
    "body":   ParagraphStyle("body", fontName="Helvetica", fontSize=9.3, leading=12.6,
                             textColor=TEXT),
    "bullet": ParagraphStyle("bullet", fontName="Helvetica", fontSize=9.3, leading=12.6,
                             textColor=TEXT, leftIndent=10, bulletIndent=1, spaceAfter=1.5),
    "cell":   ParagraphStyle("cell", fontName="Helvetica", fontSize=8.8, leading=11.4,
                             textColor=TEXT),
    "cellb":  ParagraphStyle("cellb", fontName="Helvetica-Bold", fontSize=8.8, leading=11.4,
                             textColor=colors.white),
}


def P(txt, style="body"):
    return Paragraph(txt, S[style])


def bullets(items):
    return [Paragraph(t, S["bullet"], bulletText="•") for t in items]


def rule():
    t = Table([[""]], colWidths=[AVAIL], rowHeights=[1.1])
    t.setStyle(TableStyle([("BACKGROUND", (0, 0), (-1, -1), BORDER),
                           ("TOPPADDING", (0, 0), (-1, -1), 0),
                           ("BOTTOMPADDING", (0, 0), (-1, -1), 0)]))
    return t


def section(title, flow):
    return [KeepTogether([P(title, "h2"), rule(), Spacer(1, 3)] + flow)]


def on_page(canvas, doc):
    canvas.saveState()
    canvas.setFillColor(PAGE_BG)
    canvas.rect(0, 0, W, H, fill=1, stroke=0)
    canvas.setFillColor(MUTED)
    canvas.setFont("Helvetica", 7.5)
    canvas.drawString(M, 9 * mm, "Rafiq — Employee AI Companion · solution note")
    canvas.drawRightString(W - M, 9 * mm, f"Muhammad Omaid — Magnus Mage · page {doc.page} of 2")
    canvas.restoreState()


doc = BaseDocTemplate("rafiq-solution-note.pdf", pagesize=A4,
                      leftMargin=M, rightMargin=M, topMargin=13 * mm, bottomMargin=14 * mm,
                      title="Rafiq — Employee AI Companion · Solution Note",
                      author="Muhammad Omaid — Magnus Mage",
                      subject="Ignyte × Emirates Employee AI Companion challenge — solution note",
                      creator="Magnus Mage")
frame = Frame(M, 14 * mm, AVAIL, H - 13 * mm - 14 * mm, id="main")
doc.addPageTemplates([PageTemplate(id="page", frames=[frame], onPage=on_page)])

story = []
story.append(P("Rafiq — Employee AI Companion", "title"))
story.append(Spacer(1, 2))
story.append(P("Muhammad Omaid — Magnus Mage (dev team) · entry for the Ignyte × Emirates "
               "<b>Employee AI Companion</b> challenge · prototype + this note · all data synthetic",
               "meta"))
story.append(Spacer(1, 5))
story.append(P("An employee-owned companion that carries a person through <b>both</b> required "
               "journeys — onboarding and internal mobility — knows where they are against "
               "service-level targets, answers policy questions with inline citations, starts and "
               "routes routine requests, and catches friction <b>before</b> it becomes a "
               "complaint — on a consent-first, in-region, UAE-sovereign footing."))
story.append(Spacer(1, 4))

# ── 1. problem & scope ────────────────────────────────────────────────────────
story += section("1 · Problem and scope", [
    P("At Emirates scale (131,000+ employees, ~9,700 UAE joiners last year) one employee's "
      "experience spans many teams, systems, approvals and policies. The warning signals exist — "
      "a journey event that never happened, a request sitting past its SLA, a dip in an opt-in "
      "pulse — but they are scattered across systems and surface only <b>after</b> a complaint or "
      "escalation. Employees don't know where to go; HR finds out late; service owners receive "
      "incomplete requests."),
    P("<b>Scope:</b> two journeys only (onboarding, internal mobility). <b>Out of scope:</b> the "
      "full employee lifecycle, connection to live Emirates systems, any use in performance or "
      "disciplinary decisions — enforced by design throughout."),
])

# ── 2. what we built ──────────────────────────────────────────────────────────
rows = [
    ["Part", "What it does", "Where"],
    ["Journey-state engine",
     "Deterministic rule join of journey events against journey_maps.md target days — day past "
     "target with no completion ⇒ blocker with the map's named owner. Any hidden stall scenario "
     "falls out of this one rule; no scenario-specific code.", "app/core/journey_engine.py"],
    ["Grounded answer layer",
     "BM25 retrieval with Arabic-aware normalization + heading anchors over 17 bilingual "
     "policies (EN/AR); every answer cites policy_id · section; below the floor: “I'm not sure” "
     "+ handoff — enforced by one trust_gate wrapper, not prompting discipline.",
     "app/core/rag.py, guardrails.py"],
    ["Action & routing",
     "Rules-first orchestrator: sensitive → human, status → journey, request verbs → action, "
     "else policy. Chases and requests produce structured handoff cards routed to named owners.",
     "app/agents/orchestrator.py, action_agent.py"],
    ["Friction radar + sweep",
     "Explainable weights: +0.25 overdue event, +0.15 past-SLA request, +0.10 consented pulse "
     "dip. The employee always sees the blocker first; only persistent stalls (≥2 days) escalate. "
     "Idempotent per employee/event/day.", "app/core/friction.py, services/scheduler.py"],
    ["Trust layer",
     "Consent store, employee-visible append-only audit log, PII redaction on every reply, "
     "sensitive-topic guard, one trust_gate wrapping every answer.",
     "app/core/consent.py, guardrails.py"],
]
t = Table([[P(c, "cellb" if r == 0 else "cell") for c in row] for r, row in enumerate(rows)],
          colWidths=[AVAIL * 0.175, AVAIL * 0.575, AVAIL * 0.25], repeatRows=1, hAlign="CENTER")
t.setStyle(TableStyle([
    ("BACKGROUND", (0, 0), (-1, 0), HEADER),
    ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, STRIPE]),
    ("GRID", (0, 0), (-1, -1), 0.5, BORDER),
    ("VALIGN", (0, 0), (-1, -1), "TOP"),
    ("TOPPADDING", (0, 0), (-1, -1), 3), ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
]))
story += section("2 · What we built — four deterministic-first parts and a trust layer", [t])
story.append(Spacer(1, 2))
story.append(P("LLM calls live in exactly one file (app/core/llm.py): without a key, answers are "
               "extractive from retrieved policy (same citations, zero hallucination surface); with "
               "a key, temperature-0 generation strictly inside the retrieved context. The sovereign "
               "path — Falcon-H1 Arabic or JAIS on-premise, in-region — is a one-file swap."))

# ── 3. consent, privacy, human oversight ─────────────────────────────────────
story += section("3 · Consent, privacy and human oversight", bullets([
    "<b>Opt-in consent, enforced at the signal level.</b> Pulse feedback contributes to friction "
    "only while ConsentStore records opt-in; revocation excludes the signal immediately and is "
    "confirmed to the employee. Answering a pulse without consent is acknowledged but explicitly "
    "not used (test_consent_gates_pulse_signal).",
    "<b>The employee sees their own data.</b> A “what we hold about you” panel (profile, line "
    "manager, HRBP, journey state, requests, pulse count) plus an append-only audit log of every "
    "action the companion took — employee-visible at all times.",
    "<b>Human handoffs, named owners.</b> Every intervention carries a named human owner. "
    "Sensitive topics (grievance, medical circumstances, visa problems) route to a person before "
    "any answer is attempted. Owners work a complete inbox (stage, blocker, what's been tried); "
    "their acknowledge/resolve actions appear in the employee's audit log.",
    "<b>Not a monitoring tool.</b> The manager view structurally contains no pulse data — the "
    "endpoint never reads it (test_team_view_groups_reports). HRBP and analytics views are "
    "aggregate only, never individual. Scores never feed performance or discipline.",
    "<b>Data stays home.</b> Fully self-hosted (FastAPI + pandas + dependency-free BM25); the "
    "pack is never uploaded to services that retain or train on data; in-region inference keeps "
    "personal data inside the UAE (PDPL-aligned).",
]))

# ── 4. requirements coverage ─────────────────────────────────────────────────
cov = [
    ["Brief requirement", "How Rafiq meets it"],
    ["Knows the journey stage and what's next (day 5, laptop not issued)",
     "Deterministic engine + timeline + proactive check-ins; the Home screen opens on the live blocker"],
    ["Answers policy questions, citing the source policy",
     "Grounded answer cards with policy_id · section chips; low confidence ⇒ “I'm not sure” + handoff"],
    ["Completes/starts routine requests, handing to HR, IT, learning workflows",
     "Request routing to Payroll, IT Service Desk, Learning & Development, Facilities, HR letters — with journey context attached"],
    ["Spots friction early (events, request delays, opt-in pulse)",
     "Friction radar + scheduled sweep; employee sees it first, then the named owner"],
    ["Escalates to the right owner with a summary",
     "Handoff inbox: complete cards with acknowledge/resolve, mirrored in the employee's audit log"],
    ["Arabic + English · manager view · where journeys stall",
     "True RTL flip + Arabic corpus/answers; risk-sorted team view (pulse-free); aggregate stall map by stage and owner"],
]
t2 = Table([[P(c, "cellb" if r == 0 else "cell") for c in row] for r, row in enumerate(cov)],
           colWidths=[AVAIL * 0.44, AVAIL * 0.56], repeatRows=1, hAlign="CENTER")
t2.setStyle(TableStyle([
    ("BACKGROUND", (0, 0), (-1, 0), HEADER),
    ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, STRIPE]),
    ("GRID", (0, 0), (-1, -1), 0.5, BORDER),
    ("VALIGN", (0, 0), (-1, -1), "TOP"),
    ("TOPPADDING", (0, 0), (-1, -1), 3), ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
]))
story += section("4 · Requirements coverage", [t2])

# ── 5. pilot readiness ───────────────────────────────────────────────────────
story += section("5 · Pilot readiness and deployability", bullets([
    "<b>39 tests green</b> across the engine, friction weights, RAG grounding, routing, sweep and "
    "trust surfaces — the guardrails are asserted, not promised; CI runs them on every push.",
    "<b>Configuration, not code:</b> confidence floor, escalate-after threshold, sweep interval "
    "and the demo clock all live in .env; thresholds are tuned against the pack, not by feel.",
    "<b>The pilot swap is data + connectors:</b> the loader maps columns through aliases and "
    "prefers the official pack in data/pack/ with zero code change; the policy-agnostic corpus "
    "layout is packaged for reuse by other government entities.",
]))

# ── 6. limitations ───────────────────────────────────────────────────────────
# ── 6. reproduce ────────────────────────────────────────────────────────────
story += section("6 · Reproduce it", [
    P("The prototype runs from the repository in three commands — no API keys, no cloud "
      "services, no data leaves the machine:"),
    P("<font face=\"Courier\" size=\"8.6\">uv sync&nbsp;&nbsp;·&nbsp;&nbsp;"
      "uv run uvicorn app.main:app --port 8000&nbsp;&nbsp;·&nbsp;&nbsp;"
      "uv run pytest -q&nbsp;&nbsp;(39 tests)</font>", "body"),
    P("Demo walkthrough: <font face=\"Courier\" size=\"8.6\">make run</font> then follow the "
      "two-minute tour in the repository README; the 1:46 recorded demo with narration and "
      "captions ships alongside this note, and the full pipeline that produced it is "
      "re-runnable from submission/video/make_video.py."),
])

story += section("7 · Limitations and next steps", bullets([
    "Pack stays read-only in the prototype (writes go to runtime stores); a pilot writes back "
    "through read-only-first connectors.",
    "BM25 over 17 policies is deliberately dependency-free; hybrid search + cross-encoder "
    "reranker before the corpus passes ~50 documents.",
    "Rules-first intent routing (auditable today); a small learned router once real phrasings "
    "exist. Voice designed, not built — text keeps answers cited and auditable.",
]))

doc.build(story)
print("built rafiq-solution-note.pdf")
